const projects = $('Get Projects').all().map(i => i.json).filter(p => p && p.id);
const tasks = $('Get Tasks').all().map(i => i.json).filter(t => t && t.id);

const now = new Date();
const days = n => new Date(now.getTime() - n * 86400000);
const weekAgo = days(7);
const twoWeeksAgo = days(14);
const weekAhead = new Date(now.getTime() + 7 * 86400000);

const dateOf = v => {
  if (!v) return null;
  if (typeof v === 'string') return new Date(v);
  if (v.start) return new Date(v.start);
  return null;
};
const link = p => '<' + p.url + '|' + (p.name || 'Untitled') + '>';
const openStatuses = ['Inquiry', 'Scoping', 'Proposal sent', 'Active', 'On hold'];

const created = p => dateOf(p.property_created);
const updated = p => dateOf(p.property_updated);

const newInquiries = projects.filter(p => created(p) && created(p) >= weekAgo);
const changed = projects.filter(p => !newInquiries.includes(p) && updated(p) && updated(p) >= weekAgo);
const stale = projects.filter(p => ['Inquiry', 'Scoping', 'Proposal sent'].includes(p.property_status) && updated(p) && updated(p) < twoWeeksAgo);
const pipeline = openStatuses.map(s => s + ': ' + projects.filter(p => p.property_status === s).length).join('  |  ');

const dueTasks = tasks.filter(t => t.property_status !== 'Done').filter(t => {
  const d = dateOf(t.property_due);
  return d && d <= weekAhead;
}).sort((a, b) => dateOf(a.property_due) - dateOf(b.property_due));
const overdue = dueTasks.filter(t => dateOf(t.property_due) < now);

const lines = [];
lines.push(':calendar: *Weekly digest, week of ' + now.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + '*');
lines.push('Pipeline: ' + pipeline);
lines.push('');
lines.push('*New this week (' + newInquiries.length + ')*');
lines.push(newInquiries.length ? newInquiries.map(p => '- ' + link(p) + ' (' + p.property_status + ')').join('\n') : '- none');
lines.push('');
lines.push('*Status changes (' + changed.length + ')*');
lines.push(changed.length ? changed.map(p => '- ' + link(p) + ' now ' + p.property_status).join('\n') : '- none');
lines.push('');
lines.push('*Stale, no update in 14 days (' + stale.length + ')*');
lines.push(stale.length ? stale.map(p => '- ' + link(p) + ' (' + p.property_status + ')').join('\n') : '- none');
lines.push('');
lines.push('*Tasks due this week (' + dueTasks.length + ', ' + overdue.length + ' overdue)*');
lines.push(dueTasks.length ? dueTasks.slice(0, 15).map(t => '- ' + (dateOf(t.property_due) < now ? ':warning: ' : '') + '<' + t.url + '|' + (t.name || 'Untitled') + '> due ' + dateOf(t.property_due).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })).join('\n') : '- none');

return [{ json: { text: lines.join('\n'), counts: { new: newInquiries.length, changed: changed.length, stale: stale.length, due: dueTasks.length, overdue: overdue.length } } }];
